  "《三体》三部曲 — 刘慈欣": "Trisolaris》 —",
  "特别感谢": "特别感谢",
  "所有试玩者与贡献者": "所有试玩者与贡献者",
  "征服胜利": "征服胜利",
  "暗夜之猎 · 最终裁决": "·",
  "黑暗森林的猎手倒在了自己的猎场。当最后一个异星文明的旗帜降下，人类第一次在这片冰冷的宇宙中，以绝对的力量宣告了自己的存在。": "Dark Forest . , , .",
  "这是用铁与火书写的篇章。或许有一天，银河系的废墟之上会有新的文明诞生，而他们会在古老的信号残骸中读到人类的名字——并颤抖。": ". , , —— .",
  "威慑胜利": "威慑胜利",
  "剑柄之握 · 脆弱的和平": "·",
  "手持毁灭的按钮，守住了脆弱的和平。执剑人从未按下按钮，但正是这份按下按钮的决心，让黑暗森林中的每一个猎手都选择了沉默。": ", . Swordholder , , Dark Forest .",
  "和平不是友善的馈赠，而是恐惧的产物。执剑人孤独地站在人类文明的最前沿，用自己的灵魂为全人类铸起了一面看不见的盾牌。": ", . Swordholder , .",
  "黑域胜利": "Black Domain",
  "光速墓碑 · 永恒琥珀": "·",
  "将家园永远封印在时间的琥珀中。当光速在这片区域降至零，太阳系变成了一个安全的宇宙孤岛——黑暗森林的法则在这里失效了。": ". , ——Dark Forest .",
  "这是人类向宇宙发出的安全声明：我们不会伤害任何人，也请不要伤害我们。从此，太阳系成为银河中一颗永远不会熄灭的琥珀。": ": , . , .",
  "流浪胜利": "流浪胜利",
  "星辰大海 · 行星远征": "·",
  "太阳即将毁灭，而我们带着故乡远行。地球脱离了太阳系的引力束缚，行星发动机的蓝色火焰划破了亿万年来未曾改变的夜空。": ", . , .",
  "流浪的旅途将持续两千五百年。在漫长的航行中，一代又一代人出生、成长、老去，从未见过真正的太阳。但他们知道，前方有一颗新的恒星在等待。": ". , 、 、 , . , .",
  "数字永生": "数字永生",
  "意识方舟 · 超越碳基": "·",
  "肉体消逝，但人类文明化为永恒的代码。当最后一批意识完成上传，数字方舟载着全人类的记忆、情感和梦想，驶向了虚拟的无限宇宙。": ", . , 、 , .",
  "在数字世界中，每个人都拥有无限的时间 and 空间。死亡被定义为\"选择性离线\"，而爱则是两段代码的永恒纠缠。人类终于超越了宇宙对碳基生命的一切限制。": ", and . \" \", . .",
  "死神永生 · 小宇宙": "Death's End ·",
  "归零之选 · 宇宙很大，生活更大": "· ,",
  "归零者的讯息穿越了亿万光年到达你的手中：\"尊敬的文明，大宇宙正在因质量缺失而走向热寂。请将您的小宇宙中的质量归还。\"你望着这片只属于人类的伊甸园，做出了最终的选择——": ": \" , . . \" , ——",
  "\"把质量还给大宇宙吧——为了那些还没有诞生的故事。\" 人类文明的火种化为一枚生态球，漂浮在新宇宙的起点。五磅的世界里，蓝色地球永恒旋转。宇宙很大，生活更大。": "\" —— . \" , . , . , .",
  "文明崩溃": "文明崩溃",
  "逃亡主义失控 · 内部瓦解": "·",
  "人类在恐惧中抛弃了彼此。当逃亡主义的浪潮吞没了最后的秩序，没有外敌入侵，没有宇宙灾难——文明在自己的内耗中走向了终结。": ". , , —— .",
  "散落在银河各处的逃亡飞船再也没有汇聚。每一个孤独的殖民地都在沉默中衰落，最终化为星际尘埃。黑暗森林不需要猎手——恐惧本身就是最好的猎手。": ". , . Dark Forest —— .",
  "文明灭绝": "文明灭绝",
  "最后的沉默 · 死寂星球": "·",
  "最后的光芒，也在沉默中熄灭。地球已成为一颗死寂的星球，曾经繁华的城市被尘埃覆盖，曾经的喧嚣化为永恒的寂静。": ", . , , .",
  "亿万年后，某个路过太阳系的文明探测器扫描到了第三颗行星。它们在报告中写道：\"该行星曾存在初级文明 activity 迹象，但已完全消亡。原因不明。\"": ", . : \" activity , . . \"",
  "太阳氦闪": "太阳氦闪",
  "恒星终焉 · 灰飞烟灭": "·",
  "当恒星燃尽，一切皆成灰烬。太阳在膨胀中吞噬了水星、金星，最终的耀眼白光瞬间蒸发了地球上的一切。漫长的等待终结于刺眼的光芒。": ", . 、 , . .",
  "人类曾有四百年的时间准备逃离。但争吵、犹豫、内斗消耗了一切。当氦闪的白光穿透大气层的那一刻，所有的遗憾都来不及说出口。": ". 、 、 . , .",
  "二向箔降维": "Dual-Vector Foil",
  "空间坍缩 · 降维打击": "·",
  "二向箔降临，太阳系沦为一幅没有厚度的平面画作。三维世界的物理规律被剥离，所有物质在跌落二维的深渊中化为了永恒的信息与线条。": "Dual-Vector Foil , . , .",
  "这是一场无声的毁灭。地球、恒星、乃至整个星系都被二维化，平铺在宇宙的画布上。高维的物理规律是不可逆的，你们作为三维生命，在此画作中彻底永眠。": ". Earth、 、 , . , , .",
  "永恒的流亡": "永恒的流亡",
  "星舰文明 · 无尽漂流": "·",
  "地球已被遗弃，部分人类乘坐星舰逃离。没有明确的目的地，只能在黑暗的宇宙中无尽地流浪，成为永远的星际游牧民族。": ", . , , .",
  "这是一场没有终点的远征。失去故乡的文明在星海中如浮萍般漂泊，他们将带着人类最后的基因与记忆，消失在宇宙深处。": ". , , .",
  "宇宙静默": "宇宙静默",
  "文明归零 · 绝对静止": "·",
  "战争与扩张失去了意义，文明选择了向内探索或进入深度休眠。我们不再发出任何声音，彻底融入了宇宙的背景辐射之中。": ", . , .",
  "这不是毁灭，而是终极的宁静。星空中少了一个喧闹的种族，多了一块沉默的墓碑。我们还在，但对于宇宙而言，我们已经消失。": ", . , . , , .",
  "死神永生之火种": "Death's End",
  "新周目初始自动解锁“观察者视角”功能，窥探更深层的宇宙法则。": "\" \" , .",
  "数字方舟协议": "数字方舟协议",
