  "星屑": "星屑",
  "那是上个世纪的往事。人类尚未意识到宇宙的险恶，在懵懂中向星空发出了第一声呼唤，黄金岁月还在继续。": ". , , Golden Age .",
  "人类发现了三体舰队，全世界进入危机纪元。行星防御理事会正式启动面壁计划，基础物理已被智子封锁，人类必须寻找在围剿下存活的手段！": "TrisolarisFleet, Crisis Era. Wallfacer Project, SophonBlockade, !",
  "威慑平衡正式建立，人类世界进入威慑纪元。在执剑人的威慑威压下，三体文明被迫停止了向太阳系的扩张，进入脆弱而短暂的和平冷战期。": ", Deterrence Era. Swordholder , Trisolaris , .",
  "威慑宣告中止，万有引力号启动了坐标广播，人类正式步入广播纪元。两个世界的坐标已暴露在黑暗森林法则的枪口之下，毁灭倒计时开始。": ", , Broadcast Era. Dark Forest , .",
  "太阳系黑暗森林打击临近，掩体世界群宣告落成，人类迈进掩体纪元。数十座宏伟太空城散布在气态行星背面，人类试图借此躲过光粒打击。": "Solar SystemDark Forest , , Bunker Era. , .",
  "太阳系终遭降维打击，大批光速飞船破空而去，逃亡银河系，开启银河纪元。地球不再是人类唯一的家园，人类火种从此散布在浩瀚星海。": ", Light-Speed Starship , , Galactic Era. , .",
  "大宇宙的结构在战争中进一步降维碎裂。太阳系乃至银河系的核心都已退化崩缩，人类分散在各个漂浮的碎星和微型星云间挣扎求生。这是一个万物归尘、同时也是最后的星屑纪元。": ". , . 、 .",
