  "归零者播报": "归零者播报",
  "【超膜广播】我们宇宙的总质量减少至临界值以下，宇宙将由封闭转为开放。请所有隐藏在小宇宙中的文明，交还你们借走的质量。我们将重启宇宙，回到十一维的田园时代。": "】 , . , . , .",
  "FIX-15 双写注释：mini_universe_built 同时由 filteredEvent(mini_universe_build_event, minYear=350) 写入。本事件为固定里程碑，filteredEvent 为条件性早期路径，reqNotFlag 保证幂等。": "FIX-15 : mini_universe_built filteredEvent(mini_universe_build_event, minYear=350) . , filteredEvent , reqNotFlag .",
  "星环号科学官": "星环号科学官",
  "【小宇宙对接】我们成功解析了云天明留下的647号小宇宙门控信号，并在银河系边缘建立了稳定的对接通道。这个小宇宙将成为人类文明最后的避难所——即使大宇宙死去，我们的记忆与火种也能在其中延续。": "】 Yun Tianming 647 , . —— , .",
  "【生存路线大辩论】面壁者与科学家之间爆发了一场关于人类文明终极出路的辩论。一方主张在木星背后建造掩体太空城来躲避光粒打击；另一方主张通过制造低光速黑域来发布宇宙安全声明；还有少数人坚持不计代价研发光速飞船以求逃离。执政官，请选择人类文明的未来方向。": "】Wallfacer . ； Black Domain ； Light-Speed Starship . , .",
  "掩体路线：建造木星/土星背面太空城": ": /",
  "黑域路线：发布宇宙安全声明": "Black Domain :",
  "光速飞船路线：不惜代价逃离太阳系": "Light-Speed Starship :",
  "【银河纪元·纪元宣告】太阳系已经成为一幅悬挂在宇宙中的二维画卷，而我们——星环号上的人类，是旧时代最后的见证者。从今天起，人类正式进入银河纪元。我们将以星舰为家，以星辰为路，在银河系中重新点燃文明的火焰。旧神已死，新纪已至。": "Galactic Era· 】 , —— , . , Galactic Era. , , . , .",
  "【星屑纪元·纪元宣告】宇宙正在老去。恒星逐一熄灭，黑洞缓缓蒸发，曾经辉煌的银河文明如今只剩下散落在旋臂之间的星屑聚落。我们不再有行星，不再有国家，星舰就是家园，流浪即是文明。但只要还有一束光在传播，人类的记忆就仍在宇宙中回响。": "· 】 . , , . , , , . , .",
  "【殖民地叛乱】火星殖民地发生了大规模叛乱！定居者不满地球的统治，组建了武装力量要求独立。殖民地的资源开采已陷入停滞，驻军正在紧急镇压中。": "】 ! , . , .",
  "在这个银河纪元，人类的火种已经散布在浩瀚星海之中。作为一名记录者，我将用文字铭记这段波澜壮阔的文明史诗。": "Galactic Era, . , .",
