  "材料学家 张": "材料学家 张",
  "实验意外发现，纯水可以在特定电磁场下“记住”曾接触过的物质信息，并复制其效应。这或许能彻底改变制药和材料合成。": ", \" \" , . .",
  "主流科学界": "主流科学界",
  "这是典型的伪科学！当初的“水有记忆”理论早已被证伪。在这个领域投入资源可能沦为笑柄。但万一那是真的呢？智子干扰下，物理规律是否发生了变化？": "! \" \" . . ?Sophon , ?",
