  "PIA特使": "PIA",
  "我们捕获了三体舰队的一个探测器，内部有活的“三体人”样本。三体世界传来信息，要求用这些个体换取一批被他们扣押的人类科考船船员。": "Trisolaris , \"Trisolaris \" . Trisolaris , .",
