  "【奇观：恒星级李白诗云工程】": ":",
  "天文学家": "天文学家",
  "不可思议！一个自称‘李白’的量子神级文明降临太阳系。他宣称要写出所有可能的中国古典诗词，并准备将整个太阳系的物质（包括地球）转化为量子存储介质！": "! ‘ ’ . , ( ) !",
