    "【战报】{param0} 守军成功镇压叛乱。": "[Battle Report] {param0} garrison successfully suppressed the rebellion.",
    "[攻方] {param0} 射出宏电子束流，造成 {param1} 伤害；[守方] {param2} 使用超导电磁炮反击，造成 {param3} 伤害。": "[Attacker] {param0} fired macroelectron beam, causing {param1} damage; [Defender] {param2} counter-attacked with superconducting EM cannon, causing {param3} damage.",
    "【空战总结】两支深空舰队决战终结！攻方 {param0} 的超视距战术编队成功击毁了防守方的全部作战单元，获得绝对空天控制权！": "[Combat Summary] Fleet duel concluded! Attacker {param0} over-the-horizon tactical formation destroyed all defensive units, obtaining air superiority!",
