    "资源不足！建造量子数据中心（服务器）需要 {param0} 资源。": "Insufficient Resources! Constructing Quantum Data Center (Server) requires {param0} Resources.",
    "【数字生命】第 {param0} 座量子数据中心建成。数字生命容纳容量上限提升至 {param1} 万人，MOSS自主度提升。": "[Digital Life] {param0}th Quantum Data Center constructed. Max digital life capacity increased to {param1} million, MOSS autonomy upgraded.",
    "【数字永生】{param0} 亿人口选择放弃三维肉身，意识正式上传至数字太空方舟！": "[Digital Immortality] {param0} billion people choose to upload consciousness to digital space arks!",
    "成功上传了 {param0} 亿人口的意识。当前数字永生比例: {param1}%。": "Successfully uploaded consciousness of {param0} billion people. Current digital immortality ratio: {param1}%.",
    "{param0} 目前仍在现实阵营中存活，无需复活。": "{param0} is currently alive in the real world, no resurrection needed.",
    "{param0} 已在量子架构中完成了数字重构。": "{param0} completed digital reconstruction in the quantum architecture.",
    "【数字生命重构】量子超脑 550W 成功加载了已故先烈 {param0} 的全频段思维备份，其数字体正式重回决策中枢！": "[Digital Reconstruction] Quantum supercomputer 550W successfully loaded full-band backup of late martyr {param0}, returning them to the decision hub!",
