    "【面壁计划】面壁者 {param0} 的秘密计划「{param1}」已完全部署就绪！威慑度显著上升！": "[Wallfacer Project] Wallfacer {param0}'s secret plan \"{param1}\" is fully deployed! Deterrence significantly increased!",
    "【破壁人降临】三体智子与破壁人正式识破了面壁者 {param0} 的「{param1}」计划！该计划宣告破产，{param2} 承受巨大心理打击退场。": "[Wallbreaker Arrives] Trisolaran Sophon and Wallbreaker exposed Wallfacer {param0}'s \"{param1}\" plan! The plan failed, and {param2} suffered a massive psychological blow.",
