    "[确认事件] {param0}": "[Confirmed Event] {param0}",
    "【叙事片段】{param0}": "[Narrative Slice] {param0}",
    "深空探测器在远古坐标发现了一处破碎的人类飞船遗迹。这似乎是另一个平行时间线中，毁灭于 {param0} 年、曾积累了 {param1} 文化强度的古老地球文明残留物。我们的科学家从残骸中解译出了一些技术图纸。": "Deep space probe discovered a wrecked human ship at ancient coordinates. It appears to be a remnant of an old Earth civilization destroyed in Year {param0} with {param1} Culture. Our scientists decoded some technical blueprints from it.",
    "回合推进完成：{param0} -> {param1} (存活异星文明: {param2}, 待处理事件: {param3})": "Turn advanced: {param0} -> {param1} (Surviving alien civilizations: {param2}, Pending events: {param3})",
    "已触发交互事件，年份推进暂缓 (存活异星文明: {param0}, 待处理事件: {param1})": "Interactive event triggered, turn progression paused (Surviving alien civilizations: {param0}, Pending events: {param1})",
