    "无法与已灭亡的文明 {param0} 进行外交。": "Cannot conduct diplomacy with the fallen civilization {param0}.",
    "【通信未建立】人类尚未与 {param0} 建立可外交的通信信道，无法执行外交行动。": "[Comm Offline] Communications not established with {param0}, cannot execute diplomatic actions.",
    "外交冷却中，还需等待 {param0} 回合。": "Diplomacy cooling down. Must wait {param0} turns.",
    "与 {param0} 进行外交和平谈判。关系得到改善，但因释放和平信号，对三体威慑度下降 10%（当前威慑度: {param1}%）。": "Conducted diplomatic peace talks with {param0}. Relations improved, but due to sending peace signals, deterrence toward Trisolaris decreased by 10% (Current: {param1}%).",
    "与 {param0} 进行了“三体文化与科技交流”：-30 经济，+50 资源。人类社会沉浸在三体文化的温吞中，威慑度下降 15%（当前威慑度: {param1}%）。": "Exchanged \"culture and technology\" with {param0}: -30 Economy, +50 Resources. Human society is immersed in Trisolaran culture, deterrence decreased by 15% (Current: {param1}%).",
    "【威慑提升】人类通过执剑人 {param0} 对 {param1} 进行了引力波广播威慑威胁！威慑度提升 20%，当前威慑度: {param2}%，关系恶化至极度敌对。": "[Deterrence Boost] Humans threatened {param1} via gravitational wave broadcast under Swordholder {param0}! Deterrence +20% (Current: {param2}%), relations worsened to extremely hostile.",
    "【战略同盟】在高达 {param0}% 的绝对威慑力下，{param1} 被迫妥协，与人类签署了《太阳系-三体威慑平衡和平同盟协定》！": "[Strategic Alliance] Under absolute deterrence of {param0}%, {param1} was forced to compromise and signed the \"Solar System-Trisolaris Deterrence Balance Peace Alliance Agreement\" with humanity!",
    "【结盟失败】{param0} 拒绝了和平结盟。三体文明回复：“我们在人类的执剑人身上看到了软弱与迟疑。威慑度不足以保障我们的平等共存。”": "[Alliance Failed] {param0} rejected the peace alliance. Trisolaran response: \"We saw hesitation in the human Swordholder. Deterrence is insufficient to guarantee peaceful coexistence.\"",
